import subprocess, json

def call(tool, args):
    subprocess.run(f"ft2 call {tool} '{json.dumps(args)}'", shell=True, capture_output=True, text=True)

# Pattern 3: Break / bridge - sparse, atmospheric
melody = [
    (0, 42, 3, 40), (8, 39, 3, 40), (16, 42, 3, 40), (24, 37, 3, 40),
    (32, 40, 3, 40), (40, 42, 3, 40), (48, 39, 3, 40), (56, 37, 3, 40),
]

bass = [
    (0, 25, 2, 30), (16, 28, 2, 30), (32, 25, 2, 30), (48, 28, 2, 30),
]

perc = [
    (0, 36, 4, 40), (8, 36, 4, 30), (16, 36, 4, 40), (24, 36, 4, 30),
    (32, 36, 4, 40), (40, 36, 4, 30), (48, 36, 4, 40), (56, 36, 4, 30),
]

pluck = [
    (4, 42, 5, 30), (12, 40, 5, 30), (20, 39, 5, 30), (28, 42, 5, 30),
    (36, 37, 5, 30), (44, 40, 5, 30), (52, 39, 5, 30), (60, 41, 5, 30),
]

for row, note, inst, vol in melody:
    call("pattern_set_cell", {"pattern":3, "row":row, "channel":0, "note":note, "instrument":inst, "volume":vol})
for row, note, inst, vol in bass:
    call("pattern_set_cell", {"pattern":3, "row":row, "channel":1, "note":note, "instrument":inst, "volume":vol})
for row, note, inst, vol in perc:
    call("pattern_set_cell", {"pattern":3, "row":row, "channel":3, "note":36, "instrument":inst, "volume":vol})
for row, note, inst, vol in pluck:
    call("pattern_set_cell", {"pattern":3, "row":row, "channel":2, "note":note, "instrument":inst, "volume":vol})

print("Pattern 3 done")
